// Pune Metro Guided State Machine for WhatsApp Turf Booking
const body = $input.first().json.body || $input.first().json;

let fromPhone = body.fromPhone || body.From || '+917385507049';
if (!fromPhone.startsWith('+')) fromPhone = '+91' + fromPhone.slice(-10);
const senderName = body.senderName || 'Player';
const text = (body.messageText || body.Body || body.text || '').trim();
const lower = text.toLowerCase();

// Ignore bot echoes, URLs or previews
if (!text || lower.includes('maps.google') || lower.includes('http://') || lower.includes('https://') || lower.startsWith('📍') || lower.startsWith('👋') || lower.startsWith('🏆') || lower.startsWith('⏰') || lower.startsWith('🔒') || lower.startsWith('✅') || lower.startsWith('❌')) {
  return { json: { reply: '', step: 'IGNORED' } };
}

const BACKEND = 'http://localhost:5000/api';

// 1. Load persistent session state from n8n static data
const staticData = $getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};
let session = staticData.sessions[fromPhone] || { step: 'MAIN_MENU' };

let reply = '';

// Reset / Main Menu triggers
if (/^(hi|hello|hey|menu|start|0|reset)$/i.test(lower)) {
  session = { step: 'MAIN_MENU' };
  staticData.sessions[fromPhone] = session;
  reply = `👋 Namaskar! Welcome to TurfFlow Arena 🏟️\n\nPlease choose an option:\n1️⃣ 📅 Book a Court\n2️⃣ ❌ View / Cancel Booking\n3️⃣ 💰 Enquiry & Pricing\n4️⃣ 📍 Location & Map\n\nReply with 1, 2, 3, or 4`;
  return { json: { reply, step: session.step } };
}

// 2. STATE: MAIN_MENU
if (session.step === 'MAIN_MENU') {
  if (lower === '1' || /^(book|booking|reserve|slots?)$/i.test(lower)) {
    session.step = 'SELECT_DATE';
    const today = new Date().toISOString().slice(0, 10);
    const tom = new Date(Date.now() + 86400000).toISOString().slice(0, 10);
    session.dates = { '1': today, '2': tom };
    reply = `📅 *Step 1: Choose Date*\n1️⃣ Today (${today})\n2️⃣ Tomorrow (${tom})\n\nReply with 1 or 2 (or 0 for Menu)`;
  } else if (lower === '2' || /^(cancel|refund)$/i.test(lower)) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET',
        url: `${BACKEND}/bookings/lookup?phone=${encodeURIComponent(fromPhone)}`,
        json: true
      });
      const active = (res.bookings || []).filter(b => b.status === 'confirmed' || b.status === 'pending_payment');
      if (active.length === 0) {
        reply = `ℹ️ You have no active reservations.\n\nReply 1 to book a court or 0 for Menu.`;
        session.step = 'MAIN_MENU';
      } else {
        session.step = 'CANCEL_SELECT';
        session.activeBookings = active;
        reply = `❌ *Select Booking to Cancel:*\n` +
          active.map((b, i) => `${i+1}️⃣ ${b.booking_ref} (${b.court_name}, ${b.booking_date} @ ${b.start_time}, ₹${b.total_amount})`).join('\n') +
          `\n\nReply with number (e.g. 1) or 0 for Menu`;
      }
    } catch (e) {
      reply = `⚠️ Could not fetch bookings. Please try again or reply 0.`;
    }
  } else if (lower === '3' || /^(price|pricing|rates?|cost|offers?|discounts?)$/i.test(lower)) {
    reply = `💰 *Turf Rates & Offers (per hr):*\n• Football (Turf A): ₹1200 / ₹1800 (Peak)\n• Cricket (Turf B): ₹1000 / ₹1500 (Peak)\n• Badminton (Court 1): ₹500 / ₹800 (Peak)\n\n🔥 Active Coupon: *WELCOME100* (₹100 off)\n\nReply 1 to Book or 0 for Menu.`;
  } else if (lower === '4' || /^(location|map|address|where)$/i.test(lower)) {
    reply = `📍 *TurfFlow Arena Location:*\nPlot 42, Sports Enclave, Pune 411045\nOpp. Sports Authority Dugout\n🗺️ Map: https://maps.google.com/?q=18.5204,73.8567\n\nReply 1 to Book or 0 for Menu.`;
  } else {
    reply = `ℹ️ Please reply with *1* to Book, *2* to Cancel, *3* for Pricing, or *4* for Location (or 0 for Menu).`;
  }
  staticData.sessions[fromPhone] = session;
  return { json: { reply, step: session.step } };
}

// 3. STATE: SELECT_DATE
if (session.step === 'SELECT_DATE') {
  let targetDate = session.dates ? session.dates[lower] : null;
  if (!targetDate) {
    if (lower.includes('today')) targetDate = new Date().toISOString().slice(0, 10);
    else if (lower.includes('tomorrow')) targetDate = new Date(Date.now() + 86400000).toISOString().slice(0, 10);
  }
  if (!targetDate) {
    reply = `⚠️ Please reply *1* for Today or *2* for Tomorrow (or 0 for Menu).`;
  } else {
    session.date = targetDate;
    session.step = 'SELECT_SPORT';
    reply = `🏆 *Step 2: Choose Sport for ${targetDate}*\n1️⃣ ⚽ Football (Turf A)\n2️⃣ 🏏 Box Cricket (Turf B)\n3️⃣ 🏸 Badminton (Court 1)\n4️⃣ 🏓 Pickleball (Court 2)\n\nReply with 1, 2, 3, or 4 (or 0 for Menu)`;
  }
  staticData.sessions[fromPhone] = session;
  return { json: { reply, step: session.step } };
}

// 4. STATE: SELECT_SPORT
if (session.step === 'SELECT_SPORT') {
  const sportMap = { '1': 'football', '2': 'cricket', '3': 'badminton', '4': 'pickleball' };
  const sportNames = { '1': 'Football ⚽', '2': 'Cricket 🏏', '3': 'Badminton 🏸', '4': 'Pickleball 🏓' };
  const sport = sportMap[lower] || (['football','cricket','badminton','pickleball'].find(s => lower.includes(s)));
  if (!sport) {
    reply = `⚠️ Please select a valid sport:\n1️⃣ Football\n2️⃣ Cricket\n3️⃣ Badminton\n4️⃣ Pickleball\n(Reply 0 for Menu)`;
  } else {
    session.sport = sport;
    session.sportName = sportNames[lower] || sport;
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET',
        url: `${BACKEND}/slots?sport=${session.sport}&date=${session.date}&sessionId=${encodeURIComponent(fromPhone)}`,
        json: true
      });
      const available = [];
      (res.courts || []).forEach(court => {
        const shortName = (court.court_name || court.name || '').split('—')[0].trim();
        (court.slots || []).filter(s => s.status === 'available').slice(0, 3).forEach(s => {
          available.push({
            courtId: court.court_id || court.id,
            courtName: shortName,
            startTime: s.start_time,
            endTime: s.end_time,
            price: s.price,
            isPeak: !!s.is_peak
          });
        });
      });
      if (available.length === 0) {
        reply = `😔 No open slots found for ${session.sport} on ${session.date}.\nReply 0 to choose another date or sport.`;
        session.step = 'MAIN_MENU';
      } else {
        session.availableSlots = available.slice(0, 5);
        session.step = 'SELECT_SLOT';
        reply = `⏰ *Step 3: Available Slots for ${session.sportName} (${session.date})*\n` +
          session.availableSlots.map((s, i) => `${i+1}️⃣ ${s.startTime} - ${s.endTime} (${s.courtName}) — ₹${s.price} ${s.isPeak ? '🔥' : '🟢'}`).join('\n') +
          `\n\nReply with slot number (1-${session.availableSlots.length}) or 0 for Menu`;
      }
    } catch (e) {
      reply = `⚠️ Error fetching open slots. Please reply 0 to restart.`;
    }
  }
  staticData.sessions[fromPhone] = session;
  return { json: { reply, step: session.step } };
}

// 5. STATE: SELECT_SLOT
if (session.step === 'SELECT_SLOT') {
  const idx = parseInt(lower, 10) - 1;
  const slot = session.availableSlots && session.availableSlots[idx];
  if (!slot) {
    reply = `⚠️ Please enter a valid slot number (1-${session.availableSlots ? session.availableSlots.length : 1}) or 0 for Menu.`;
  } else {
    try {
      const lockRes = await this.helpers.httpRequest({
        method: 'POST',
        url: `${BACKEND}/slots/lock`,
        body: { courtId: slot.courtId, date: session.date, startTime: slot.startTime, lockedBy: fromPhone, ttlSeconds: 300 },
        json: true
      });
      if (!lockRes.success) {
        reply = `⚠️ This slot was just taken! Please choose another slot or reply 0.`;
      } else {
        const initRes = await this.helpers.httpRequest({
          method: 'POST',
          url: `${BACKEND}/bookings/initiate`,
          body: {
            courtId: slot.courtId,
            sportId: session.sport,
            date: session.date,
            startTime: slot.startTime,
            customerName: senderName,
            customerPhone: fromPhone
          },
          json: true
        });
        session.bookingRef = initRes.booking?.booking_ref || 'TRF-HOLD';
        session.step = 'AWAIT_PAYMENT';
        reply = `🔒 *Slot Held for 5 Minutes!*\n• Sport: ${session.sportName}\n• Court: ${slot.courtName}\n• Time: ${session.date} @ ${slot.startTime}\n• Total: ₹${slot.price}\n\n👉 Tap to pay & confirm:\nhttp://localhost:3000/checkout?ref=${session.bookingRef}\n\nReply *CONFIRM* after paying or *CANCEL* to release.`;
      }
    } catch (e) {
      reply = `⚠️ Failed to reserve slot. Please reply 0 to restart.`;
    }
  }
  staticData.sessions[fromPhone] = session;
  return { json: { reply, step: session.step } };
}

// 6. STATE: AWAIT_PAYMENT
if (session.step === 'AWAIT_PAYMENT') {
  if (lower === 'confirm' || lower === 'pay' || lower === 'paid') {
    try {
      const confRes = await this.helpers.httpRequest({
        method: 'POST',
        url: `${BACKEND}/bookings/confirm`,
        body: { bookingRef: session.bookingRef, paymentId: 'pay_wa_' + Date.now() },
        json: true
      });
      session.step = 'MAIN_MENU';
      reply = `✅ *Booking Confirmed!* 🎉\n• Pass: *${session.bookingRef}*\n• Status: Confirmed\n\nYour slot is permanently booked across website & venue dashboard!\nReply *MENU* anytime.`;
    } catch (e) {
      reply = `⚠️ Could not verify payment. Reply CONFIRM to retry or 0 for Menu.`;
    }
  } else if (lower === 'cancel') {
    session.step = 'MAIN_MENU';
    reply = `🔓 Slot hold released.\n\nReply 1 to book another court or 0 for Menu.`;
  } else {
    reply = `👉 Please complete payment at http://localhost:3000/checkout?ref=${session.bookingRef}\n\nReply *CONFIRM* when done or *CANCEL* to release.`;
  }
  staticData.sessions[fromPhone] = session;
  return { json: { reply, step: session.step } };
}

// 7. STATE: CANCEL_SELECT
if (session.step === 'CANCEL_SELECT') {
  const idx = parseInt(lower, 10) - 1;
  const booking = session.activeBookings && session.activeBookings[idx];
  if (!booking) {
    reply = `⚠️ Please select a valid number (1-${session.activeBookings ? session.activeBookings.length : 1}) or 0 for Menu.`;
  } else {
    session.cancelTarget = booking;
    session.step = 'CANCEL_CONFIRM';
    reply = `⚠️ *Confirm Cancellation:*\n• Ref: *${booking.booking_ref}*\n• Court: ${booking.court_name}\n• Date: ${booking.booking_date} @ ${booking.start_time}\n• Refund: ₹${booking.total_amount} (100% refund)\n\nReply *CONFIRM CANCEL* to cancel or *NO* to keep booking.`;
  }
  staticData.sessions[fromPhone] = session;
  return { json: { reply, step: session.step } };
}

// 8. STATE: CANCEL_CONFIRM
if (session.step === 'CANCEL_CONFIRM') {
  if (lower === 'confirm cancel' || lower === 'confirm' || lower === 'yes') {
    try {
      const cRes = await this.helpers.httpRequest({
        method: 'POST',
        url: `${BACKEND}/bookings/cancel`,
        body: { bookingRef: session.cancelTarget.booking_ref, phone: fromPhone, reason: 'Customer requested via WhatsApp' },
        json: true
      });
      session.step = 'MAIN_MENU';
      reply = `✅ *Booking Cancelled Successfully!*\n• Ref: ${session.cancelTarget.booking_ref}\n• Refund: ₹${cRes.refund_amount || session.cancelTarget.total_amount} initiated to your account.\n\nReply *MENU* to return to main menu.`;
    } catch (e) {
      reply = `⚠️ Failed to cancel booking. Reply CONFIRM CANCEL to retry or 0 for Menu.`;
    }
  } else {
    session.step = 'MAIN_MENU';
    reply = `👍 Cancellation aborted. Your booking remains active!\n\nReply *MENU* for main menu.`;
  }
  staticData.sessions[fromPhone] = session;
  return { json: { reply, step: session.step } };
}

reply = `👋 Reply *MENU* to start.`;
staticData.sessions[fromPhone] = session;
return { json: { reply, step: session.step } };
